            new Quote { Id = "https://en.wikiquote.org/wiki/Ayn_Rand", Text = "It took centuries of intellectual, philosophical development to achieve political freedom. It was a long struggle, stretching from Aristotle to John Locke to the Founding Fathers.", Author = "Ayn Rand" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ayn_Rand", Text = "Let no man posture as an advocate of peace if he proposes or supports any social system that initiates the use of force against individual men, in any form.", Author = "Ayn Rand" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Ayn_Rand", Text = "Man-every man-is an end in himself, not a means to the ends of others; he must live for his own sake, neither sacrificing himself to others nor sacrificing others to himself.", Author = "Ayn Rand" },
